# Money is in rupees (numeric) here, not paise, so charts and spreadsheets read it directly.
# Dates are joined through date keys (YYYYMMDD). Aadhaar, phone numbers and addresses are never
# copied into this schema.
TODAY = "(now() AT TIME ZONE 'Asia/Kolkata')::date"
RS = "/100.0)::numeric(14,2)"


def k(expr: str) -> str:
    return f"to_char({expr},'YYYYMMDD')::int"


ANALYTICS = f"""
CREATE SCHEMA IF NOT EXISTS analytics;
COMMENT ON SCHEMA analytics IS 'Read-only star schema for reports and charts. Rebuilt by analytics.refresh().';
CREATE TABLE IF NOT EXISTS analytics.refresh_log (refreshed_at timestamptz NOT NULL DEFAULT now(), seconds numeric);

-- ---------------------------------------------------------------- dimensions
CREATE MATERIALIZED VIEW IF NOT EXISTS analytics.dim_date AS
SELECT {k('d')} AS date_key, d::date AS date, extract(day FROM d)::int AS day, extract(month FROM d)::int AS month,
       to_char(d, 'Mon') AS month_name, extract(quarter FROM d)::int AS quarter, extract(year FROM d)::int AS year,
       -- Indian financial year, April to March: FY 2026-27 starts on 1 April 2026.
       CASE WHEN extract(month FROM d) >= 4 THEN extract(year FROM d)::int ELSE extract(year FROM d)::int - 1 END AS fy_start_year,
       extract(isodow FROM d)::int AS weekday, extract(week FROM d)::int AS iso_week,
       date_trunc('month', d)::date AS month_start, (date_trunc('month', d) + interval '1 month - 1 day')::date AS month_end
FROM generate_series(date '2010-01-01', date '2040-12-31', interval '1 day') AS d;
CREATE UNIQUE INDEX IF NOT EXISTS dim_date_key ON analytics.dim_date (date_key);

CREATE MATERIALIZED VIEW analytics.dim_borrower AS
SELECT b.id AS borrower_key, b.code, COALESCE(b.name_en, b.name_ta) AS name, b.name_en, b.name_ta,
       b.occupation, b.town, b.district, b.pincode, b.preferred_language AS language, b.status,
       {k("(b.created_at AT TIME ZONE 'Asia/Kolkata')::date")} AS joined_date_key,
       (b.aadhaar_hash IS NOT NULL) AS kyc_complete, b.erased_at IS NOT NULL AS erased,
       (SELECT count(*) FROM guarantor g WHERE g.borrower_id = b.id)::int AS guarantors
FROM borrower b WHERE b.deleted_at IS NULL;
CREATE UNIQUE INDEX ON analytics.dim_borrower (borrower_key);

CREATE MATERIALIZED VIEW analytics.dim_loan AS
SELECT l.id AS loan_key, l.loan_no, l.borrower_id AS borrower_key, l.method, l.frequency, l.rate, l.rate_basis,
       CASE WHEN l.rate_basis = 'month' THEN l.rate ELSE l.rate / 12 END::numeric(9,4) AS rate_monthly,
       l.term_value, l.term_unit, l.installments, (l.principal{RS} AS principal,
       (l.amount_handed_over{RS} AS handed_over, (l.total_interest{RS} AS scheduled_interest,
       l.true_cost_monthly, l.security_kind, l.ltv_percent, l.disbursal_mode, l.status, l.recovery_status,
       l.topup_of_id IS NOT NULL AS is_topup, l.penalty_mode, l.closed_reason,
       {k('l.disbursal_date')} AS disbursal_date_key, {k('l.maturity_date')} AS maturity_date_key,
       CASE WHEN l.closed_on IS NULL THEN NULL ELSE {k('l.closed_on')} END AS closed_date_key,
       CASE WHEN l.principal < 2500000 THEN 'under 25k' WHEN l.principal < 5000000 THEN '25k-50k'
            WHEN l.principal < 10000000 THEN '50k-1L' WHEN l.principal < 20000000 THEN '1L-2L'
            WHEN l.principal < 50000000 THEN '2L-5L' ELSE '5L+' END AS size_band
FROM loan l WHERE l.deleted_at IS NULL;
CREATE UNIQUE INDEX ON analytics.dim_loan (loan_key);
CREATE INDEX ON analytics.dim_loan (borrower_key);

CREATE MATERIALIZED VIEW analytics.dim_security AS
SELECT c.id AS security_key, c.loan_id AS loan_key, c.kind, c.vehicle_type, c.vehicle_condition, c.make_model,
       c.year AS vehicle_year, c.village, c.taluk, c.district, (c.value{RS} AS value, c.lien_noted_on_rc, c.ec_checked,
       c.insurance_expiry, c.released_on IS NOT NULL AS released
FROM collateral c JOIN loan l ON l.id = c.loan_id WHERE l.deleted_at IS NULL;
CREATE UNIQUE INDEX ON analytics.dim_security (security_key);

-- ---------------------------------------------------------------- facts
-- One row per installment (rows replaced by a part payment or restructure are kept, flagged).
CREATE MATERIALIZED VIEW analytics.fact_installment AS
SELECT si.id AS installment_key, si.loan_id AS loan_key, l.borrower_id AS borrower_key, si.seq,
       {k('si.due_date')} AS due_date_key, (si.installment{RS} AS installment,
       (si.principal_part{RS} AS principal, (si.interest_part{RS} AS interest,
       (si.paid_principal{RS} AS paid_principal, (si.paid_interest{RS} AS paid_interest,
       (si.paid_penalty{RS} AS paid_late_fee, ((si.waived_principal + si.waived_interest){RS} AS waived,
       (si.waived_penalty{RS} AS waived_late_fee,
       (CASE WHEN si.replaced THEN 0 ELSE GREATEST(si.principal_part + si.interest_part - si.paid_principal
             - si.paid_interest - si.waived_principal - si.waived_interest, 0) END{RS} AS unpaid,
       si.settled, si.replaced,
       CASE WHEN NOT si.settled AND si.due_date < {TODAY} THEN {TODAY} - si.due_date ELSE 0 END AS days_overdue
FROM schedule_item si JOIN loan l ON l.id = si.loan_id WHERE l.deleted_at IS NULL;
CREATE UNIQUE INDEX ON analytics.fact_installment (installment_key);
CREATE INDEX ON analytics.fact_installment (due_date_key);

-- One row per payment (a reversal is negative), split into principal, interest, late fee and charges.
CREATE MATERIALIZED VIEW analytics.fact_payment AS
SELECT p.id AS payment_key, p.loan_id AS loan_key, l.borrower_id AS borrower_key, p.receipt_no, p.kind, p.mode,
       {k('p.paid_on')} AS paid_date_key,
       ((CASE WHEN p.kind = 'reversal' THEN -p.amount ELSE p.amount END){RS} AS amount,
       (COALESCE(a.principal, 0){RS} AS principal, (COALESCE(a.interest, 0){RS} AS interest,
       (COALESCE(a.late_fee, 0){RS} AS late_fee, (COALESCE(f.charges, 0){RS} AS charges
FROM payment p JOIN loan l ON l.id = p.loan_id
LEFT JOIN (SELECT payment_id, sum(principal_part) AS principal, sum(interest_part) AS interest, sum(penalty_part) AS late_fee
           FROM payment_allocation GROUP BY payment_id) a ON a.payment_id = p.id
LEFT JOIN (SELECT payment_id, sum(amount) AS charges FROM fee_allocation GROUP BY payment_id) f ON f.payment_id = p.id
WHERE l.deleted_at IS NULL;
CREATE UNIQUE INDEX ON analytics.fact_payment (payment_key);
CREATE INDEX ON analytics.fact_payment (paid_date_key);

-- One row per loan given.
CREATE MATERIALIZED VIEW analytics.fact_disbursement AS
SELECT l.id AS loan_key, l.borrower_id AS borrower_key, {k('l.disbursal_date')} AS date_key, l.disbursal_mode AS mode,
       (l.principal{RS} AS principal, (l.amount_handed_over{RS} AS handed_over,
       (COALESCE(c.deducted, 0){RS} AS charges_taken_out, (COALESCE(c.added, 0){RS} AS charges_added
FROM loan l
LEFT JOIN (SELECT loan_id, sum(amount) FILTER (WHERE treatment = 'deducted') AS deducted,
                  sum(amount) FILTER (WHERE treatment = 'added') AS added FROM loan_charge GROUP BY loan_id) c ON c.loan_id = l.id
WHERE l.deleted_at IS NULL;
CREATE UNIQUE INDEX ON analytics.fact_disbursement (loan_key);

-- One row per charge added after a loan was given (bounce, seizure, foreclosure ...).
CREATE MATERIALIZED VIEW analytics.fact_charge AS
SELECT f.id AS charge_key, f.loan_id AS loan_key, l.borrower_id AS borrower_key, f.kind, {k('f.charged_on')} AS charged_date_key,
       (f.amount{RS} AS amount, (f.paid{RS} AS paid, (f.waived{RS} AS waived, ((f.amount - f.paid - f.waived){RS} AS due
FROM loan_fee f JOIN loan l ON l.id = f.loan_id WHERE l.deleted_at IS NULL;
CREATE UNIQUE INDEX ON analytics.fact_charge (charge_key);

-- Every rupee in or out of the cash book (the daily log), with the category for own expenses and income.
CREATE MATERIALIZED VIEW analytics.fact_cash_flow AS
SELECT row_number() OVER (ORDER BY d.entry_date, d.created_at, d.source_id, d.direction) AS flow_key,
       {k('d.entry_date')} AS date_key, d.direction, d.source_type, d.mode, d.loan_id AS loan_key,
       (d.amount{RS} AS amount, cat.name_en AS category_en, cat.name_ta AS category_ta
FROM daily_log d
LEFT JOIN cash_entry ce ON d.source_type = 'cash_entry' AND ce.id = d.source_id
LEFT JOIN category cat ON cat.id = ce.category_id;
CREATE UNIQUE INDEX ON analytics.fact_cash_flow (flow_key);
CREATE INDEX ON analytics.fact_cash_flow (date_key);

-- Month-end snapshot per loan, from the month it was given to this month (or the month it closed):
-- principal still owed, amount overdue, days past due of the oldest unpaid installment, and what
-- was collected that month. Installments replaced later count until the reschedule date.
CREATE MATERIALIZED VIEW analytics.fact_loan_month AS
WITH months AS (
  SELECT l.id AS loan_id, l.borrower_id, l.principal,
         (m + interval '1 month - 1 day')::date AS month_end, m::date AS month_start
  FROM loan l,
       generate_series(date_trunc('month', l.disbursal_date),
                       date_trunc('month', LEAST(COALESCE(l.closed_on, {TODAY}), {TODAY})), interval '1 month') AS m
  WHERE l.deleted_at IS NULL
),
moves AS (
  SELECT si.loan_id, a.schedule_item_id, p.paid_on AS on_date, a.principal_part AS pr, a.interest_part AS ir, true AS paid
    FROM payment_allocation a JOIN payment p ON p.id = a.payment_id JOIN schedule_item si ON si.id = a.schedule_item_id
  UNION ALL
  SELECT loan_id, schedule_item_id, adjusted_on, principal_part, interest_part, false FROM loan_adjustment
),
item_left AS (
  SELECT m.loan_id, m.month_end, si.due_date,
         si.principal_part + si.interest_part
           - COALESCE((SELECT sum(mv.pr + mv.ir) FROM moves mv
                       WHERE mv.schedule_item_id = si.id AND mv.on_date <= m.month_end), 0) AS left_amount
  FROM months m JOIN schedule_item si ON si.loan_id = m.loan_id AND si.due_date <= m.month_end
  WHERE NOT si.replaced OR EXISTS (SELECT 1 FROM reschedule r WHERE r.loan_id = si.loan_id AND r.paid_on > m.month_end)
)
SELECT m.loan_id AS loan_key, m.borrower_id AS borrower_key, {k('m.month_end')} AS month_end_key,
       ((m.principal - COALESCE(pp.pr, 0)){RS} AS principal_outstanding,
       (COALESCE(o.overdue, 0){RS} AS overdue_amount,
       COALESCE(m.month_end - o.oldest, 0) AS days_past_due,
       CASE WHEN o.oldest IS NULL THEN '0 current' WHEN m.month_end - o.oldest <= 30 THEN '1-30'
            WHEN m.month_end - o.oldest <= 60 THEN '31-60' WHEN m.month_end - o.oldest <= 90 THEN '61-90'
            ELSE '90+' END AS dpd_bucket,
       (COALESCE(c.pr, 0){RS} AS principal_collected, (COALESCE(c.ir, 0){RS} AS interest_collected
FROM months m
LEFT JOIN LATERAL (SELECT sum(mv.pr) AS pr FROM moves mv WHERE mv.loan_id = m.loan_id AND mv.on_date <= m.month_end) pp ON true
LEFT JOIN LATERAL (SELECT sum(left_amount) FILTER (WHERE left_amount > 0) AS overdue,
                          min(due_date) FILTER (WHERE left_amount > 0) AS oldest
                   FROM item_left s WHERE s.loan_id = m.loan_id AND s.month_end = m.month_end) o ON true
LEFT JOIN LATERAL (SELECT sum(mv.pr) AS pr, sum(mv.ir) AS ir FROM moves mv
                   WHERE mv.loan_id = m.loan_id AND mv.paid AND mv.on_date BETWEEN m.month_start AND m.month_end) c ON true;
CREATE UNIQUE INDEX ON analytics.fact_loan_month (loan_key, month_end_key);
CREATE INDEX ON analytics.fact_loan_month (month_end_key);

-- ---------------------------------------------------------------- refresh and access
CREATE OR REPLACE FUNCTION analytics.refresh() RETURNS void LANGUAGE plpgsql AS $$
DECLARE started timestamptz := clock_timestamp();
BEGIN
  REFRESH MATERIALIZED VIEW analytics.dim_borrower;
  REFRESH MATERIALIZED VIEW analytics.dim_loan;
  REFRESH MATERIALIZED VIEW analytics.dim_security;
  REFRESH MATERIALIZED VIEW analytics.fact_installment;
  REFRESH MATERIALIZED VIEW analytics.fact_payment;
  REFRESH MATERIALIZED VIEW analytics.fact_disbursement;
  REFRESH MATERIALIZED VIEW analytics.fact_charge;
  REFRESH MATERIALIZED VIEW analytics.fact_cash_flow;
  REFRESH MATERIALIZED VIEW analytics.fact_loan_month;
  INSERT INTO analytics.refresh_log (refreshed_at, seconds)
    VALUES (now(), extract(epoch FROM clock_timestamp() - started));
END $$;

DO $do$ BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'analytics_reader') THEN
    CREATE ROLE analytics_reader NOLOGIN;
  END IF;
END $do$;
GRANT USAGE ON SCHEMA analytics TO analytics_reader;
GRANT SELECT ON ALL TABLES IN SCHEMA analytics TO analytics_reader;
ALTER DEFAULT PRIVILEGES IN SCHEMA analytics GRANT SELECT ON TABLES TO analytics_reader;
SELECT analytics.refresh();
"""
